using System.Security.Cryptography;
using System.Text;
using Npgsql;
using NpgsqlTypes;
using UDrive.Api.Common;
using UDrive.Api.Models;

namespace UDrive.Api.Services;

public sealed class TrackingService(string connectionString)
{
    private NpgsqlConnection Open()=>new(connectionString);

    public async Task<ServiceResult<LocationAcceptedDto>> UpdateAsync(Guid userId,DriverLocationUpdateRequest request,CancellationToken ct)
    {
        if(request.DeviceTimestamp<DateTimeOffset.UtcNow.AddHours(-6)||request.DeviceTimestamp>DateTimeOffset.UtcNow.AddMinutes(5))return ServiceResult<LocationAcceptedDto>.Fail(400,"invalid_timestamp","Device timestamp is outside the allowed range.");
        await using var cn=Open();await cn.OpenAsync(ct);await using var tx=await cn.BeginTransactionAsync(ct);
        const string ownership=@"select dp.id,o.trip_status from udrive.bookings b join udrive.trip_operations o on o.booking_id=b.id join udrive.driver_profiles dp on dp.id=b.driver_profile_id where b.id=@booking and dp.user_id=@user for update";
        Guid driver;string status;await using(var cmd=new NpgsqlCommand(ownership,cn,tx)){cmd.Parameters.AddWithValue("booking",request.TripId);cmd.Parameters.AddWithValue("user",userId);await using var r=await cmd.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))return ServiceResult<LocationAcceptedDto>.Fail(403,"tracking_forbidden","You are not assigned to this trip.");driver=r.GetGuid(0);status=r.GetString(1);}
        var allowed=new[]{"DriverAssigned","DriverAccepted","DriverEnRoute","DriverArrived","TripStarted","Emergency"};if(!allowed.Contains(status))return ServiceResult<LocationAcceptedDto>.Fail(409,"tracking_inactive","Location updates are disabled for this trip status.");
        var server=DateTimeOffset.UtcNow;var duplicate=false;await using(var exists=new NpgsqlCommand("select count(*) from udrive.trip_location_history where driver_profile_id=@driver and client_event_id=@event",cn,tx)){exists.Parameters.AddWithValue("driver",driver);exists.Parameters.AddWithValue("event",request.ClientEventId);duplicate=Convert.ToInt32(await exists.ExecuteScalarAsync(ct))>0;}if(duplicate){await tx.CommitAsync(ct);return ServiceResult<LocationAcceptedDto>.Ok(new(request.ClientEventId,server,true,false,true));}
        var last=await GetLastAsync(cn,tx,driver,ct);if(last is not null){var elapsed=(request.DeviceTimestamp-last.Value.Time).TotalSeconds;var meters=Haversine(last.Value.Lat,last.Value.Lng,request.Latitude,request.Longitude);if(elapsed<2)return ServiceResult<LocationAcceptedDto>.Fail(429,"location_rate_limited","Location updates are arriving too quickly.");if(meters<5&&elapsed<30){await tx.CommitAsync(ct);return ServiceResult<LocationAcceptedDto>.Ok(new(request.ClientEventId,server,false,false,false));}}
        const string insert=@"insert into udrive.trip_location_history(id,client_event_id,booking_id,driver_profile_id,location,accuracy_meters,heading,speed_kph,battery_level,permission_status,device_timestamp,server_timestamp,source,is_emergency,created_at) values(gen_random_uuid(),@event,@booking,@driver,ST_SetSRID(ST_MakePoint(@lng,@lat),4326)::geography,@accuracy,@heading,@speed,@battery,@permission,@device,@server,@source,@emergency,@server)";
        await using(var cmd=new NpgsqlCommand(insert,cn,tx)){Add(cmd,"event",request.ClientEventId);Add(cmd,"booking",request.TripId);Add(cmd,"driver",driver);Add(cmd,"lng",request.Longitude);Add(cmd,"lat",request.Latitude);Add(cmd,"accuracy",request.Accuracy,NpgsqlDbType.Double);Add(cmd,"heading",request.Heading,NpgsqlDbType.Double);Add(cmd,"speed",request.SpeedKph,NpgsqlDbType.Double);Add(cmd,"battery",request.BatteryLevel,NpgsqlDbType.Smallint);Add(cmd,"permission",request.PermissionStatus,NpgsqlDbType.Text);Add(cmd,"device",request.DeviceTimestamp);Add(cmd,"server",server);Add(cmd,"source",request.Source,NpgsqlDbType.Text);Add(cmd,"emergency",status=="Emergency");await cmd.ExecuteNonQueryAsync(ct);}
        const string latest=@"insert into udrive.driver_latest_locations(driver_profile_id,booking_id,location,accuracy_meters,heading,speed_kph,battery_level,permission_status,device_timestamp,server_timestamp,source,is_emergency,updated_at) values(@driver,@booking,ST_SetSRID(ST_MakePoint(@lng,@lat),4326)::geography,@accuracy,@heading,@speed,@battery,@permission,@device,@server,@source,@emergency,@server) on conflict(driver_profile_id) do update set booking_id=excluded.booking_id,location=excluded.location,accuracy_meters=excluded.accuracy_meters,heading=excluded.heading,speed_kph=excluded.speed_kph,battery_level=excluded.battery_level,permission_status=excluded.permission_status,device_timestamp=excluded.device_timestamp,server_timestamp=excluded.server_timestamp,source=excluded.source,is_emergency=excluded.is_emergency,updated_at=excluded.updated_at where udrive.driver_latest_locations.device_timestamp<=excluded.device_timestamp";
        await using(var cmd=new NpgsqlCommand(latest,cn,tx)){Add(cmd,"driver",driver);Add(cmd,"booking",request.TripId);Add(cmd,"lng",request.Longitude);Add(cmd,"lat",request.Latitude);Add(cmd,"accuracy",request.Accuracy,NpgsqlDbType.Double);Add(cmd,"heading",request.Heading,NpgsqlDbType.Double);Add(cmd,"speed",request.SpeedKph,NpgsqlDbType.Double);Add(cmd,"battery",request.BatteryLevel,NpgsqlDbType.Smallint);Add(cmd,"permission",request.PermissionStatus,NpgsqlDbType.Text);Add(cmd,"device",request.DeviceTimestamp);Add(cmd,"server",server);Add(cmd,"source",request.Source,NpgsqlDbType.Text);Add(cmd,"emergency",status=="Emergency");await cmd.ExecuteNonQueryAsync(ct);}
        await tx.CommitAsync(ct);return ServiceResult<LocationAcceptedDto>.Ok(new(request.ClientEventId,server,false,true,(server-request.DeviceTimestamp).TotalMinutes>2));
    }

    public async Task<ServiceResult<IReadOnlyList<ActiveTrackingListItemDto>>> ActiveAsync(string? search,string? city,string? status,bool emergencyOnly,bool staleOnly,CancellationToken ct)
    {
        await using var cn=Open();await cn.OpenAsync(ct);const string sql=@"select b.id,b.booking_reference,u.full_name,concat(v.make,' ',v.model),v.registration_number,o.trip_status,coalesce(b.pickup_label,''),l.server_timestamp,(l.server_timestamp is null or l.server_timestamp<now()-interval '2 minutes'),(o.trip_status='Emergency' or coalesce(l.is_emergency,false)),l.speed_kph,l.heading,l.accuracy_meters from udrive.bookings b join udrive.trip_operations o on o.booking_id=b.id join udrive.driver_profiles dp on dp.id=b.driver_profile_id join udrive.users u on u.id=dp.user_id join udrive.vehicles v on v.id=b.vehicle_id left join udrive.driver_latest_locations l on l.booking_id=b.id and l.driver_profile_id=dp.id where o.trip_status in ('DriverAccepted','DriverEnRoute','DriverArrived','TripStarted','Emergency') and (@search is null or b.booking_reference ilike '%'||@search||'%' or u.full_name ilike '%'||@search||'%' or v.registration_number ilike '%'||@search||'%') and (@city is null or b.pickup_label ilike '%'||@city||'%' or b.destination_label ilike '%'||@city||'%') and (@status is null or o.trip_status=@status) and (not @emergency or o.trip_status='Emergency' or coalesce(l.is_emergency,false)) and (not @stale or l.server_timestamp is null or l.server_timestamp<now()-interval '2 minutes') order by (o.trip_status='Emergency') desc,o.last_activity_at desc";var list=new List<ActiveTrackingListItemDto>();await using var cmd=new NpgsqlCommand(sql,cn);Add(cmd,"search",search,NpgsqlDbType.Text);Add(cmd,"city",city,NpgsqlDbType.Text);Add(cmd,"status",status,NpgsqlDbType.Text);Add(cmd,"emergency",emergencyOnly);Add(cmd,"stale",staleOnly);await using var r=await cmd.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))list.Add(new(r.GetGuid(0),r.GetString(1),r.GetString(2),r.GetString(3),r.GetString(4),r.GetString(5),r.GetString(6),r.IsDBNull(7)?null:r.GetFieldValue<DateTimeOffset>(7),r.GetBoolean(8),r.GetBoolean(9),r.IsDBNull(10)?null:r.GetDouble(10),r.IsDBNull(11)?null:r.GetDouble(11),r.IsDBNull(12)?null:r.GetDouble(12)));return ServiceResult<IReadOnlyList<ActiveTrackingListItemDto>>.Ok(list);
    }

    public async Task<ServiceResult<TripTrackingDto>> PrivateAsync(Guid userId,bool privileged,Guid bookingId,CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);if(!privileged){await using var access=new NpgsqlCommand(@"select count(*) from udrive.bookings b left join udrive.driver_profiles dp on dp.id=b.driver_profile_id where b.id=@id and (b.customer_user_id=@user or dp.user_id=@user)",cn);access.Parameters.AddWithValue("id",bookingId);access.Parameters.AddWithValue("user",userId);if(Convert.ToInt32(await access.ExecuteScalarAsync(ct))==0)return ServiceResult<TripTrackingDto>.Fail(403,"tracking_forbidden","You cannot view this trip.");}var model=await LoadTrackingAsync(cn,bookingId,ct);return model is null?ServiceResult<TripTrackingDto>.Fail(404,"trip_not_found","Trip not found."):ServiceResult<TripTrackingDto>.Ok(model);}

    public async Task<ServiceResult<TrackingLinkDto>> CreateLinkAsync(Guid actor,Guid bookingId,CreateTrackingLinkRequest request,CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);var allowed=await HasBookingAccessAsync(cn,actor,bookingId,ct);if(!allowed)return ServiceResult<TrackingLinkDto>.Fail(403,"tracking_forbidden","You cannot share this trip.");var token=Convert.ToHexString(RandomNumberGenerator.GetBytes(32)).ToLowerInvariant();var hash=Hash(token);var expires=DateTimeOffset.UtcNow.AddMinutes(request.ExpiresInMinutes);await using var cmd=new NpgsqlCommand("insert into udrive.trip_tracking_tokens(id,booking_id,token_hash,created_by_user_id,expires_at,created_at,updated_at) values(gen_random_uuid(),@booking,@hash,@actor,@expires,now(),now())",cn);cmd.Parameters.AddWithValue("booking",bookingId);cmd.Parameters.AddWithValue("hash",hash);cmd.Parameters.AddWithValue("actor",actor);cmd.Parameters.AddWithValue("expires",expires);await cmd.ExecuteNonQueryAsync(ct);return ServiceResult<TrackingLinkDto>.Created(new(token,expires));}
    public async Task<ServiceResult<bool>> RevokeLinksAsync(Guid actor,Guid bookingId,CancellationToken ct){await using var cn=Open();await cn.OpenAsync(ct);if(!await HasBookingAccessAsync(cn,actor,bookingId,ct))return ServiceResult<bool>.Fail(403,"tracking_forbidden","You cannot revoke this link.");await using var cmd=new NpgsqlCommand("update udrive.trip_tracking_tokens set revoked_at=now(),updated_at=now() where booking_id=@booking and revoked_at is null",cn);cmd.Parameters.AddWithValue("booking",bookingId);await cmd.ExecuteNonQueryAsync(ct);return ServiceResult<bool>.Ok(true);}
    public async Task<ServiceResult<TripTrackingDto>> PublicAsync(string token,CancellationToken ct){if(token.Length<40)return ServiceResult<TripTrackingDto>.Fail(404,"link_not_found","Tracking link is invalid or expired.");await using var cn=Open();await cn.OpenAsync(ct);Guid booking;await using(var cmd=new NpgsqlCommand(@"update udrive.trip_tracking_tokens t set last_accessed_at=now(),access_count=access_count+1,updated_at=now() from udrive.trip_operations o where t.booking_id=o.booking_id and t.token_hash=@hash and t.revoked_at is null and t.expires_at>now() and o.trip_status not in ('TripCompleted','Cancelled') returning t.booking_id",cn)){cmd.Parameters.AddWithValue("hash",Hash(token));var x=await cmd.ExecuteScalarAsync(ct);if(x is null)return ServiceResult<TripTrackingDto>.Fail(404,"link_not_found","Tracking link is invalid or expired.");booking=(Guid)x;}var model=await LoadTrackingAsync(cn,booking,ct);return model is null?ServiceResult<TripTrackingDto>.Fail(404,"trip_not_found","Trip not found."):ServiceResult<TripTrackingDto>.Ok(model with { DriverName=model.DriverName is null?null:model.DriverName.Split(' ')[0] });}

    private static async Task<bool> HasBookingAccessAsync(NpgsqlConnection cn,Guid user,Guid booking,CancellationToken ct){await using var cmd=new NpgsqlCommand(@"select count(*) from udrive.bookings b left join udrive.driver_profiles dp on dp.id=b.driver_profile_id where b.id=@booking and (b.customer_user_id=@user or dp.user_id=@user or exists(select 1 from udrive.user_roles ur where ur.user_id=@user and ur.role in ('SuperAdmin','Admin','Manager','Operations')))",cn);cmd.Parameters.AddWithValue("booking",booking);cmd.Parameters.AddWithValue("user",user);return Convert.ToInt32(await cmd.ExecuteScalarAsync(ct))>0;}
    private static async Task<TripTrackingDto?> LoadTrackingAsync(NpgsqlConnection cn,Guid booking,CancellationToken ct){const string sql=@"select b.id,b.booking_reference,o.trip_status,coalesce(b.pickup_label,''),coalesce(b.destination_label,''),ST_Y(rr.pickup_location::geometry),ST_X(rr.pickup_location::geometry),ST_Y(rr.destination_location::geometry),ST_X(rr.destination_location::geometry),du.full_name,case when v.id is null then null else concat(v.make,' ',v.model) end,v.registration_number,ST_Y(l.location::geometry),ST_X(l.location::geometry),l.accuracy_meters,l.heading,l.speed_kph,l.battery_level,l.device_timestamp,l.server_timestamp,(l.server_timestamp<now()-interval '2 minutes'),(l.server_timestamp>=now()-interval '2 minutes'),coalesce(l.is_emergency,false) from udrive.bookings b join udrive.trip_operations o on o.booking_id=b.id left join udrive.ride_requests rr on rr.id=b.ride_request_id left join udrive.driver_profiles dp on dp.id=b.driver_profile_id left join udrive.users du on du.id=dp.user_id left join udrive.vehicles v on v.id=b.vehicle_id left join udrive.driver_latest_locations l on l.booking_id=b.id where b.id=@id";Guid id;string reference,status,pickup,destination;double? plat,plng,dlat,dlng;string? driver,vehicle,reg;TrackingPointDto? latest;await using(var cmd=new NpgsqlCommand(sql,cn)){cmd.Parameters.AddWithValue("id",booking);await using var r=await cmd.ExecuteReaderAsync(ct);if(!await r.ReadAsync(ct))return null;id=r.GetGuid(0);reference=r.GetString(1);status=r.GetString(2);pickup=r.GetString(3);destination=r.GetString(4);plat=r.IsDBNull(5)?null:r.GetDouble(5);plng=r.IsDBNull(6)?null:r.GetDouble(6);dlat=r.IsDBNull(7)?null:r.GetDouble(7);dlng=r.IsDBNull(8)?null:r.GetDouble(8);driver=r.IsDBNull(9)?null:r.GetString(9);vehicle=r.IsDBNull(10)?null:r.GetString(10);reg=r.IsDBNull(11)?null:r.GetString(11);latest=r.IsDBNull(12)?null:new(r.GetDouble(12),r.GetDouble(13),r.IsDBNull(14)?null:r.GetDouble(14),r.IsDBNull(15)?null:r.GetDouble(15),r.IsDBNull(16)?null:r.GetDouble(16),r.IsDBNull(17)?null:r.GetInt16(17),r.GetFieldValue<DateTimeOffset>(18),r.GetFieldValue<DateTimeOffset>(19),r.GetBoolean(20),r.GetBoolean(21),r.GetBoolean(22));}var path=new List<TrackingPointDto>();await using(var cmd=new NpgsqlCommand("select ST_Y(location::geometry),ST_X(location::geometry),accuracy_meters,heading,speed_kph,battery_level,device_timestamp,server_timestamp,(server_timestamp<now()-interval '2 minutes'),(server_timestamp>=now()-interval '2 minutes'),is_emergency from udrive.trip_location_history where booking_id=@id and server_timestamp>now()-interval '6 hours' order by server_timestamp desc limit 200",cn)){cmd.Parameters.AddWithValue("id",booking);await using var r=await cmd.ExecuteReaderAsync(ct);while(await r.ReadAsync(ct))path.Add(new(r.GetDouble(0),r.GetDouble(1),r.IsDBNull(2)?null:r.GetDouble(2),r.IsDBNull(3)?null:r.GetDouble(3),r.IsDBNull(4)?null:r.GetDouble(4),r.IsDBNull(5)?null:r.GetInt16(5),r.GetFieldValue<DateTimeOffset>(6),r.GetFieldValue<DateTimeOffset>(7),r.GetBoolean(8),r.GetBoolean(9),r.GetBoolean(10)));}path.Reverse();return new(id,reference,status,pickup,destination,plat,plng,dlat,dlng,driver,vehicle,reg,latest,path);}
    private static async Task<(double Lat,double Lng,DateTimeOffset Time)?> GetLastAsync(NpgsqlConnection cn,NpgsqlTransaction tx,Guid driver,CancellationToken ct){await using var cmd=new NpgsqlCommand("select ST_Y(location::geometry),ST_X(location::geometry),device_timestamp from udrive.driver_latest_locations where driver_profile_id=@driver",cn,tx);cmd.Parameters.AddWithValue("driver",driver);await using var r=await cmd.ExecuteReaderAsync(ct);return await r.ReadAsync(ct)?(r.GetDouble(0),r.GetDouble(1),r.GetFieldValue<DateTimeOffset>(2)):null;}
    private static string Hash(string token)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(token))).ToLowerInvariant();
    private static double Haversine(double lat1,double lon1,double lat2,double lon2){const double r=6371000;double p1=lat1*Math.PI/180,p2=lat2*Math.PI/180,dp=(lat2-lat1)*Math.PI/180,dl=(lon2-lon1)*Math.PI/180;var a=Math.Sin(dp/2)*Math.Sin(dp/2)+Math.Cos(p1)*Math.Cos(p2)*Math.Sin(dl/2)*Math.Sin(dl/2);return r*2*Math.Atan2(Math.Sqrt(a),Math.Sqrt(1-a));}
    private static void Add(NpgsqlCommand cmd,string name,object? value,NpgsqlDbType? type=null){if(value is null){cmd.Parameters.Add(new NpgsqlParameter(name,type??NpgsqlDbType.Text){Value=DBNull.Value});}else if(type.HasValue){cmd.Parameters.Add(new NpgsqlParameter(name,type.Value){Value=value});}else cmd.Parameters.AddWithValue(name,value);}
}
